"""Lazy CARLA adapter for an operator-reviewed connected alley packet.

The packet is an original source claim that local review must corroborate. A
successful simulation never proves the legal status of the road or blocking.
"""
from __future__ import annotations

import hashlib
import io
import json
import math
import threading
import time
from pathlib import Path

from access_measurement import ASSIGNMENT
from parking_controller import ParkingController

VIEWS = (("overview", 1920, 1080), ("approach", 1280, 720),
         ("reference_corner", 1280, 720), ("driver_reference", 1280, 720))


def _triple(value, label):
    if (not isinstance(value, list) or len(value) != 3 or
            any(type(v) not in (int, float) or not math.isfinite(v) for v in value)):
        raise ValueError("reviewed alley packet lacks " + label)
    return tuple(float(v) for v in value)


def _source(value, label):
    if not isinstance(value, dict) or not value.get("path") or not value.get("sha256"):
        raise ValueError("reviewed alley packet lacks " + label + " source")
    path = Path(value["path"])
    if not path.is_file() or hashlib.sha256(path.read_bytes()).hexdigest() != value["sha256"]:
        raise ValueError("reviewed alley " + label + " source changed")
    return path


def validate_packet(packet_path: Path, case_id: str) -> dict:
    if not case_id.startswith(ASSIGNMENT + "__"):
        raise ValueError("alley packet exact case mismatch")
    packet = json.loads(Path(packet_path).read_text(encoding="utf-8"))
    if packet.get("case_id") != case_id or not packet.get("reviewer"):
        raise ValueError("reviewed alley packet case or reviewer missing")
    if not packet.get("vehicle_blueprint_id") or not packet.get("ego_vehicle_id"):
        raise ValueError("reviewed alley vehicle identity missing")
    _source(packet.get("opendrive_source"), "OpenDRIVE")
    for field in ("highway_source", "alley_classification_source", "cul_de_sac_source",
                  "start_connection_source", "end_connection_source",
                  "property_abutting_source", "driveway_ownership_source",
                  "vehicular_use_source"):
        _source(packet.get(field), field)
    if packet.get("highway_status") is not True or packet.get("cul_de_sac") is not False:
        raise ValueError("qualifying connected highway alley unverified")
    if not packet.get("property_id") or packet.get("access_kind") not in ("driveway", "entrance"):
        raise ValueError("abutting property access identity missing")
    _triple(packet.get("spawn_xyz_m"), "vehicle spawn")
    _triple(packet.get("spawn_rpy_deg"), "vehicle spawn rotation")
    cameras = packet.get("cameras")
    if not isinstance(cameras, list) or len(cameras) != 4:
        raise ValueError("reviewed four-camera plan missing")
    for expected, camera in zip(VIEWS, cameras):
        if (camera.get("name"), camera.get("width"), camera.get("height")) != expected:
            raise ValueError("reviewed camera identity or dimensions differ")
        if not camera.get("pose_source") or not camera.get("reviewer"):
            raise ValueError("reviewed camera pose provenance missing")
        _triple(camera.get("location_xyz_m"), camera["name"] + " position")
        _triple(camera.get("rotation_rpy_deg"), camera["name"] + " rotation")
        if type(camera.get("fov_deg")) not in (int, float) or not 1 <= camera["fov_deg"] <= 170:
            raise ValueError("reviewed camera field of view invalid")
    return packet


def _transform(carla, location, rotation):
    x, y, z = _triple(location, "position")
    roll, pitch, yaw = _triple(rotation, "rotation")
    return carla.Transform(carla.Location(x=x, y=y, z=z),
                           carla.Rotation(roll=roll, pitch=pitch, yaw=yaw))


class CameraBuffer:
    def __init__(self):
        self.condition = threading.Condition()
        self.frames = {}
        self.errors = []

    def receive(self, name, width, height, image):
        try:
            if (type(image.frame) is not int or image.width != width or
                    image.height != height or len(image.raw_data) != width * height * 4):
                raise ValueError("original camera shape or frame invalid")
            from PIL import Image
            rgb = Image.frombytes("RGBA", (width, height), bytes(image.raw_data),
                                  "raw", "BGRA").convert("RGB")
            data = io.BytesIO()
            rgb.save(data, format="PNG")
            with self.condition:
                key = (name, image.frame)
                if key in self.frames:
                    raise ValueError("duplicate original camera frame")
                self.frames[key] = data.getvalue()
                self.condition.notify_all()
        except Exception as error:
            with self.condition:
                self.errors.append(error)
                self.condition.notify_all()

    def read(self, name, frame, timeout_s=15):
        deadline = time.monotonic() + timeout_s
        with self.condition:
            while (name, frame) not in self.frames and not self.errors:
                remaining = deadline - time.monotonic()
                if remaining <= 0:
                    raise ValueError("original camera frame missing: " + name)
                self.condition.wait(remaining)
            if self.errors:
                raise ValueError("original camera callback failed: " + str(self.errors[0]))
            return self.frames.pop((name, frame))


class Session:
    native_attested = True

    def __init__(self, client, world, ego, sensors, prior, packet, carla, direction):
        self.client, self.world, self.ego = client, world, ego
        self.sensors, self.prior, self.packet, self.carla = sensors, prior, packet, carla
        self.direction = direction
        self.cameras = CameraBuffer()
        self.controller = None
        self.last = None
        self.last_state = None
        self.restored = False
        self.closed = False
        self.pipeline_capture = None
        self.capture_complete = False
        for name, sensor, width, height in sensors:
            sensor.listen(lambda image, n=name, w=width, h=height:
                          self.cameras.receive(n, w, h, image))

    def get_map_packet(self, case_id):
        if case_id != self.packet["case_id"]:
            raise ValueError("alley case differs from reviewed packet")
        excluded = ("cameras", "opendrive_source", "spawn_xyz_m", "spawn_rpy_deg",
                    "vehicle_blueprint_id", "reviewer")
        packet = {k: v for k, v in self.packet.items() if k not in excluded}
        packet["source_kind"] = "original_native_geometry"
        packet["map_sha256"] = self.packet["opendrive_source"]["sha256"]
        return packet

    def get_opendrive_bytes(self):
        return self.world.get_map().to_opendrive().encode("utf-8")

    def start(self, plan):
        if plan["case_id"] != self.packet["case_id"]:
            raise ValueError("parking plan case differs from reviewed packet")
        self.controller = ParkingController(plan)

    def tick(self):
        if self.controller is None:
            raise ValueError("parking plan not started")
        transform = self.ego.get_transform()
        velocity = self.ego.get_velocity()
        xy = [float(transform.location.x), float(transform.location.y)]
        speed = math.sqrt(velocity.x ** 2 + velocity.y ** 2 + velocity.z ** 2)
        before = self.world.get_snapshot()
        control = self.controller.step(xy_m=xy,
                                       yaw_rad=math.radians(transform.rotation.yaw),
                                       speed_mps=speed, time_s=float(before.timestamp.elapsed_seconds))
        self.ego.apply_control(self.carla.VehicleControl(
            throttle=control["throttle"], brake=control["brake"], steer=control["steer"]))
        frame = self.world.tick()
        snapshot = self.world.get_snapshot()
        if snapshot.frame != frame:
            raise ValueError("Native tick/snapshot frame mismatch")
        self.last = (int(frame), float(snapshot.timestamp.elapsed_seconds))
        self.last_state = control["phase"]
        return {"frame": self.last[0], "time_s": self.last[1]}

    def read_footprint(self, frame):
        if self.last is None or frame != self.last[0]:
            raise ValueError("original vehicle footprint frame mismatch")
        vertices = self.ego.bounding_box.get_world_vertices(self.ego.get_transform())
        xy = [(float(v.x), float(v.y)) for v in vertices]
        if len(xy) != 8:
            raise ValueError("original ego bounding box incomplete")
        # Four unique ground-plane corners; the native box may repeat upper vertices.
        corners = sorted(set((round(x, 6), round(y, 6)) for x, y in xy))
        if len(corners) != 4:
            raise ValueError("original ego ground footprint invalid")
        cx = sum(x for x, _ in corners) / 4
        cy = sum(y for _, y in corners) / 4
        corners.sort(key=lambda p: math.atan2(p[1] - cy, p[0] - cx))
        return {"frame": frame, "time_s": self.last[1],
                "vehicle_id": self.packet["ego_vehicle_id"],
                "polygon_m": [[x, y] for x, y in corners]}

    def read_activity(self, frame):
        if self.last is None or frame != self.last[0]:
            raise ValueError("original activity frame mismatch")
        velocity = self.ego.get_velocity()
        speed = math.sqrt(velocity.x ** 2 + velocity.y ** 2 + velocity.z ** 2)
        phase = {"approach": "approaching", "braking": "stopping",
                 "hold": "parked", "depart": "departing", "done": "departing"}[self.last_state]
        return {"frame": frame, "time_s": self.last[1], "state": phase,
                "speed_mps": float(speed)}

    def read_cameras(self, frame):
        if self.last is None or frame != self.last[0]:
            raise ValueError("original camera time mismatch")
        return {name: {"frame": frame, "time_s": self.last[1],
                       "png": self.cameras.read(name, frame)} for name, _, _, _ in self.sensors}

    def brake(self):
        self.ego.apply_control(self.carla.VehicleControl(throttle=0, brake=1))

    def cleanup(self):
        if self.closed:
            return
        self.closed = True
        errors = []
        if self.pipeline_capture is not None:
            try:
                self.pipeline_capture.close(confirmed=self.capture_complete)
            except Exception as error:
                errors.append(error)
        for _, sensor, _, _ in reversed(self.sensors):
            try:
                sensor.stop()
                sensor.destroy()
            except Exception as error:
                errors.append(error)
        try:
            self.ego.destroy()
        except Exception as error:
            errors.append(error)
        try:
            self.world.apply_settings(self.prior)
            now = self.world.get_settings()
            self.restored = (now.synchronous_mode == self.prior.synchronous_mode and
                             now.fixed_delta_seconds == self.prior.fixed_delta_seconds and
                             now.no_rendering_mode == self.prior.no_rendering_mode)
            if not self.restored:
                errors.append(ValueError("world settings restoration readback differs"))
        except Exception as error:
            errors.append(error)
        if errors:
            raise RuntimeError("CARLA alley cleanup failed: " + "; ".join(map(str, errors)))


def open_session(case_id: str, packet_path: Path, host: str, port: int,
                 direction: int = 1) -> Session:
    """Connect only to a leased server and return an owned session."""
    packet = validate_packet(packet_path, case_id)
    if direction not in (-1, 1):
        raise ValueError("reviewed alley approach direction invalid")
    import carla
    client = carla.Client(host, int(port))
    client.set_timeout(30.0)
    world = client.get_world()
    if world.get_settings().no_rendering_mode:
        raise ValueError("Native world rendering disabled")
    loaded = world.get_map().to_opendrive().encode("utf-8")
    if hashlib.sha256(loaded).hexdigest() != packet["opendrive_source"]["sha256"]:
        raise ValueError("loaded OpenDRIVE differs from reviewed alley source")
    prior = world.get_settings()
    ego = None
    sensors = []
    try:
        settings = world.get_settings()
        settings.synchronous_mode = True
        settings.fixed_delta_seconds = .05
        settings.no_rendering_mode = False
        world.apply_settings(settings)
        blueprints = world.get_blueprint_library()
        vehicle_bp = blueprints.find(packet["vehicle_blueprint_id"])
        vehicle_bp.set_attribute("role_name", "scenario-alley-ego")
        ego = world.try_spawn_actor(vehicle_bp,
                                    _transform(carla, packet["spawn_xyz_m"], packet["spawn_rpy_deg"]))
        if ego is None:
            raise ValueError("reviewed alley ego spawn failed")
        if packet["ego_vehicle_id"] != "ego":
            raise ValueError("reviewed ego role must be ego")
        for camera in packet["cameras"]:
            bp = blueprints.find("sensor.camera.rgb")
            for key, value in (("image_size_x", camera["width"]),
                               ("image_size_y", camera["height"]),
                               ("fov", camera["fov_deg"]), ("sensor_tick", "0.0")):
                bp.set_attribute(key, str(value))
            sensor = world.spawn_actor(bp, _transform(carla, camera["location_xyz_m"],
                                                      camera["rotation_rpy_deg"]))
            sensors.append((camera["name"], sensor, camera["width"], camera["height"]))
        return Session(client, world, ego, sensors, prior, packet, carla, direction)
    except BaseException:
        for _, sensor, _, _ in reversed(sensors):
            try:
                sensor.stop()
                sensor.destroy()
            except Exception:
                pass
        if ego is not None:
            ego.destroy()
        world.apply_settings(prior)
        raise

"""Low-level route tracking, braking, hold and departure for an alley attempt.

Controls are requests; only Native readback establishes actual parking motion.
"""
from __future__ import annotations

import math


def _point(value):
    if not isinstance(value, (tuple, list)) or len(value) != 2:
        raise ValueError("vehicle position missing")
    x, y = value
    if any(type(a) not in (int, float) or not math.isfinite(a) for a in (x, y)):
        raise ValueError("vehicle position nonfinite")
    return float(x), float(y)


class ParkingController:
    def __init__(self, plan: dict):
        self.plan = plan
        self.phase = "approach"
        self.hold_since = None
        self.target = _point(plan["target_xy_m"])
        self.depart = _point(plan["depart_xy_m"])
        self.axis = _point(plan["route_axis_xy"])
        self.direction = plan["direction"]
        if abs(math.hypot(*self.axis) - 1) > .001 or self.direction not in (-1, 1):
            raise ValueError("invalid surveyed route axis")

    def step(self, *, xy_m, yaw_rad, speed_mps, time_s) -> dict:
        xy = _point(xy_m)
        if any(type(x) not in (int, float) or not math.isfinite(x)
               for x in (yaw_rad, speed_mps, time_s)) or speed_mps < 0:
            raise ValueError("Native vehicle state invalid")
        axis = (self.axis[0] * self.direction, self.axis[1] * self.direction)
        dx, dy = xy[0] - self.target[0], xy[1] - self.target[1]
        remaining = -(dx * axis[0] + dy * axis[1])
        lateral = abs(dx * -axis[1] + dy * axis[0])
        if lateral > 3.0:
            raise ValueError("vehicle left surveyed alley route")
        if self.phase == "approach" and remaining < 1.0:
            self.phase = "braking"
        if self.phase == "braking" and speed_mps <= .1 and math.hypot(dx, dy) <= .75:
            self.phase = "hold"
            self.hold_since = time_s
        if self.phase == "hold" and time_s - self.hold_since >= self.plan["controller"]["hold_min_s"]:
            self.phase = "depart"
        if self.phase == "depart" and math.dist(xy, self.depart) <= 1.0:
            self.phase = "done"
        if self.phase in ("braking", "hold", "done"):
            return {"phase": self.phase, "throttle": 0.0, "brake": 1.0, "steer": 0.0}
        desired_yaw = math.atan2(axis[1], axis[0])
        heading_error = (desired_yaw - yaw_rad + math.pi) % (2 * math.pi) - math.pi
        signed_lateral = dx * -axis[1] + dy * axis[0]
        steer = max(-.45, min(.45, 1.2 * heading_error - .12 * signed_lateral))
        target_speed = min(4.0, max(.8, remaining / 2)) if self.phase == "approach" else 3.0
        throttle = max(0.0, min(.6, .2 * (target_speed - speed_mps)))
        brake = max(0.0, min(.6, .3 * (speed_mps - target_speed)))
        return {"phase": self.phase, "throttle": throttle, "brake": brake, "steer": steer}

"""Measure original alley parking footprint against abutting-property access.

Polygon overlap is an engineering observation. The statutory word "block" is
left for source review; no overlap area or clearance is made a legal cutoff.
"""
from __future__ import annotations

import hashlib
import json
import math
from pathlib import Path


ASSIGNMENT = "testing__C229404__NRS-484B-477-2__motor_vehicle_driver"
SOURCE_NAMES = ("frame_map", "alley_geometry", "vehicle_footprint", "activity")


def _load_source(root: Path, entry: dict) -> dict:
    rel = Path(entry["path"])
    if rel.is_absolute() or ".." in rel.parts:
        raise ValueError("original source path escapes attempt")
    path = (root / rel).resolve()
    if not path.is_relative_to(root.resolve()) or not path.is_file():
        raise ValueError("original alley source missing")
    raw = path.read_bytes()
    if hashlib.sha256(raw).hexdigest() != entry["sha256"]:
        raise ValueError("original alley source hash mismatch")
    return json.loads(raw)


def _polygon(raw: object, name: str) -> list[tuple[float, float]]:
    if not isinstance(raw, list) or len(raw) < 3:
        raise ValueError(f"{name} polygon absent")
    points = []
    for point in raw:
        if (not isinstance(point, list) or len(point) != 2 or
                any(type(x) not in (int, float) or not math.isfinite(x) for x in point)):
            raise ValueError(f"{name} polygon point invalid")
        points.append((float(point[0]), float(point[1])))
    if len(set(points)) != len(points):
        raise ValueError(f"{name} polygon repeats a point")
    if _signed_area(points) < 0:
        points.reverse()
    if abs(_signed_area(points)) < 1e-9:
        raise ValueError(f"{name} polygon has no area")
    signs = []
    for i in range(len(points)):
        a, b, c = points[i - 1], points[i], points[(i + 1) % len(points)]
        cross = (b[0] - a[0]) * (c[1] - b[1]) - (b[1] - a[1]) * (c[0] - b[0])
        if abs(cross) > 1e-9:
            signs.append(cross > 0)
    if not signs or len(set(signs)) != 1:
        raise ValueError(f"{name} polygon must be convex")
    return points


def _signed_area(points: list[tuple[float, float]]) -> float:
    return sum(a[0] * b[1] - b[0] * a[1]
               for a, b in zip(points, points[1:] + points[:1])) / 2


def _overlap_area(subject: list[tuple[float, float]],
                  clip: list[tuple[float, float]]) -> float:
    """Convex polygon intersection via half-plane clipping, in square metres."""
    result = subject
    for a, b in zip(clip, clip[1:] + clip[:1]):
        def side(p):
            return (b[0] - a[0]) * (p[1] - a[1]) - (b[1] - a[1]) * (p[0] - a[0])

        def intersection(p, q):
            sp, sq = side(p), side(q)
            fraction = sp / (sp - sq)
            return (p[0] + fraction * (q[0] - p[0]),
                    p[1] + fraction * (q[1] - p[1]))

        previous = result
        result = []
        if not previous:
            break
        for p, q in zip(previous[-1:] + previous[:-1], previous):
            inside_p, inside_q = side(p) >= -1e-10, side(q) >= -1e-10
            if inside_p != inside_q:
                result.append(intersection(p, q))
            if inside_q:
                result.append(q)
    return abs(_signed_area(result)) if len(result) >= 3 else 0.0


def measure(root: Path, inventory: dict, case_id: str) -> dict:
    root = Path(root)
    if not case_id.startswith(ASSIGNMENT + "__") or inventory.get("case_id") != case_id:
        raise ValueError("exact parking case mismatch")
    if inventory.get("source_kind") != "original_native":
        raise ValueError("original Native source required")
    sources = inventory.get("sources")
    if not isinstance(sources, dict) or set(sources) != set(SOURCE_NAMES):
        raise ValueError("complete original alley source inventory required")
    packets = {name: _load_source(root, sources[name]) for name in SOURCE_NAMES}
    geometry = packets["alley_geometry"]
    if (geometry.get("source_kind") != "original_native_geometry" or
            geometry.get("highway_status") is not True or
            geometry.get("cul_de_sac") is not False or
            not geometry.get("highway_source") or
            not geometry.get("alley_classification_source") or
            not geometry.get("cul_de_sac_source") or
            not geometry.get("property_abutting_source") or
            not geometry.get("property_id") or
            not geometry.get("driveway_ownership_source") or
            not geometry.get("vehicular_use_source")):
        raise ValueError("qualifying alley and abutting driveway provenance incomplete")
    access = _polygon(geometry.get("access_corridor_polygon_m"), "access corridor")
    if geometry.get("access_kind") not in ("driveway", "entrance"):
        raise ValueError("access kind must be driveway or entrance")
    frames = packets["frame_map"].get("frames")
    diagnostic = inventory.get("diagnostic_fixture") is True
    if not isinstance(frames, list) or len(frames) not in ((9, 900) if diagnostic else (900,)):
        raise ValueError("original 900-frame history missing" if not diagnostic
                         else "nine-frame diagnostic history missing")
    first = frames[0].get("frame")
    if type(first) is not int or [r.get("frame") for r in frames] != list(range(first, first + len(frames))):
        raise ValueError("original frames not consecutive")
    times = [r.get("time_s") for r in frames]
    if any(type(t) not in (int, float) or not math.isfinite(t) for t in times) or any(
            abs(b - a - .05) > .005 for a, b in zip(times, times[1:])):
        raise ValueError("original frame clock not 20 Hz")
    body = packets["vehicle_footprint"]
    activity = packets["activity"]
    for name, packet in (("vehicle footprint", body), ("activity", activity)):
        if packet.get("case_id") != case_id or packet.get("source_kind") != "original_native":
            raise ValueError(f"{name} original identity mismatch")
        if not isinstance(packet.get("samples"), list) or len(packet["samples"]) != len(frames):
            raise ValueError(f"{name} original history incomplete")
    measured = []
    for frame, b, state in zip(frames, body["samples"], activity["samples"]):
        for name, row in (("vehicle footprint", b), ("activity", state)):
            if row.get("frame") != frame["frame"] or row.get("time_s") != frame["time_s"]:
                raise ValueError(f"{name} frame/time join mismatch")
        if b.get("vehicle_id") != geometry.get("ego_vehicle_id"):
            raise ValueError("original body vehicle identity mismatch")
        footprint = _polygon(b.get("polygon_m"), "vehicle footprint")
        if state.get("state") not in ("approaching", "stopping", "standing", "parked", "departing"):
            raise ValueError("actual stopping/standing/parking activity missing")
        if type(state.get("speed_mps")) not in (int, float) or state["speed_mps"] < 0:
            raise ValueError("original speed invalid")
        if state["state"] in ("standing", "parked") and state["speed_mps"] > .1:
            raise ValueError("stationary phase speed inconsistent")
        if state["state"] in ("stopping", "standing", "parked"):
            measured.append({"frame": frame["frame"], "time_s": frame["time_s"],
                             "state": state["state"],
                             "access_intrusion_area_m2": round(_overlap_area(footprint, access), 8)})
    if not any(row["state"] == "parked" for row in measured):
        raise ValueError("actual parked phase absent")
    if not diagnostic and sum(row["state"] == "parked" for row in measured) < 400:
        raise ValueError("original parked hold shorter than engineering 20-second target")
    return {"format": "c229404-original-access-measurement-v1", "case_id": case_id,
            "source_sha256": {name: sources[name]["sha256"] for name in SOURCE_NAMES},
            "original_frames": len(frames), "measured_halt_frames": len(measured),
            "access_kind": geometry["access_kind"], "property_id": geometry["property_id"],
            "max_access_intrusion_area_m2": max(r["access_intrusion_area_m2"] for r in measured),
            "halt_samples": measured, "statutory_blocking_judgment": "unresolved"}


def main() -> None:
    import argparse
    parser = argparse.ArgumentParser()
    parser.add_argument("--attempt", type=Path, required=True)
    parser.add_argument("--case", required=True)
    parser.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()
    if args.output.exists():
        raise ValueError("refusing to overwrite original access measurement")
    inventory = json.loads((args.attempt / "inventory.json").read_text())
    result = measure(args.attempt, inventory, args.case)
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text(json.dumps(result, indent=2) + "\n")


if __name__ == "__main__":
    main()
